(function(root){
'use strict';
root.createNursingRecord=function(ctx){
 const {$,esc,toast}=ctx,C=root.NursingCore;
 let pane='plan',people=[],peopleStay='',loadedAt=0,loadError='',loading=false,taskDay='',taskScope='Toutes',taskOwner='';
 const now=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date()).replace(' ','T');
 const time=s=>s?String(s).replace('T',' '):'Non renseigné';
 const profile=()=>ctx.access?.()?.profile;
 const canWrite=()=>ctx.canWrite()&&peopleStay===ctx.stay().id&&people.length>0&&!loadError;
 const field=(name,label,type='text',value='',attrs='required')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
 const text=(name,label,required=true,value='')=>`<label class="wide">${label}<textarea name="${name}" maxlength="4000" ${required?'required':''}>${esc(value)}</textarea></label>`;
 const options=(rows,value)=>rows.map(([id,label])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`).join('');
 const select=(name,label,rows,value,required=true)=>`<label>${label}<select name="${name}" ${required?'required':''}>${options(rows,value)}</select></label>`;
 const owner=(value='')=>select('ownerId','Responsable identifié',[['','Choisir un professionnel'],...people.map(p=>[p.user_id,p.display_name+' · '+p.profession])],value);
 const form=(id,body,button)=>canWrite()?`<form id="${id}" class="nursing-form"><div class="formgrid">${body}</div><p role="alert" class="nursing-error"></p><button class="primary">${button}</button></form>`:'<p class="muted">Saisie disponible après chargement de l’équipe pour un compte habilité.</p>';
 const base=(kind,v)=>{const who=profile(),person=people.find(p=>p.user_id===v.ownerId);return {id:crypto.randomUUID(),kind,occurredAt:v.occurredAt||now(),recordedAt:new Date().toISOString(),authorId:who.user_id,authorLabel:who.display_name,ownerId:v.ownerId,ownerLabel:person?.display_name||''}};
 const state=()=>C.project(ctx.stay().nursingRecord||[]);
 function append(entries){
  if(!canWrite())return 'Droits ou équipe indisponibles : rechargez le dossier.';
  const stay=ctx.stay(),before=stay.nursingRecord||[],after=[...before,...entries],error=C.validateJournal(before,after,people,profile());
  if(error)return error;
  stay.nursingRecord=after;ctx.trace('Dossier infirmier · '+entries.length+' trace(s) ajoutée(s)');return '';
 }
 function bind(id,build){const f=$('#'+id);if(f)f.onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(f));let error;try{const entries=build(v);error=typeof entries==='string'?entries:append(entries)}catch{error='Vérifiez les champs et les horaires.'}if(error){f.querySelector('[role=alert]').textContent=error;return}draw($('#nursing-host'));toast('Trace préparée · vérifiez la confirmation serveur')};}
 function responsible(row){const current=people.find(p=>p.user_id===row.ownerId);return `<p class="nursing-owner"><strong>Responsable :</strong> ${esc(current?.display_name||row.ownerLabel)}${people.length&&!current?' · habilitation actuelle à vérifier':''}</p>`}
 function badge(status,warn=false){return `<span class="pill ${warn?'warn':status==='Réalisée'||status==='Résolue'?'good':''}">${esc(status)}</span>`}
 function journal(ref){const rows=(ctx.stay().nursingRecord||[]).filter(e=>e.id===ref||[e.planId,e.taskId,e.deviceId,e.alertId].includes(ref));return `<details class="nursing-history"><summary>Historique · ${rows.length} trace(s)</summary>${rows.map(e=>`<article><strong>${esc(e.kind)} · ${esc(time(e.occurredAt))}</strong><p>${esc(e.status||e.title||e.findings||e.target||'Création')} ${esc(e.note||'')}</p><p>${esc(e.authorLabel)} · responsable : ${esc(e.ownerLabel)} · saisie ${esc(e.recordedAt)}</p></article>`).join('')}</details>`}
 function render(){
  const stay=ctx.stay();$('#content').innerHTML='<section id="nursing-host" data-stay="'+esc(stay.id)+'"></section>';
  if(peopleStay!==stay.id){people=[];peopleStay='';loadedAt=0;loadError='';taskOwner='';taskDay=''}
  draw($('#nursing-host'));
  if(peopleStay!==stay.id||Date.now()-loadedAt>30000)loadPeople(stay.id);
 }
 async function loadPeople(id){
  loading=true;loadError='';const host=$('#nursing-host');
  try{const response=await fetch('/api/workspace/access/care-team?stay='+encodeURIComponent(id),{credentials:'same-origin',cache:'no-store'});const data=await response.json();if(!response.ok)throw new Error(data.error||'Équipe indisponible.');if(ctx.stay()?.id!==id)return;people=data.people;peopleStay=id;loadedAt=Date.now()}
  catch(error){if(ctx.stay()?.id===id)loadError=error.message}
  finally{loading=false;if($('#nursing-host')===host&&ctx.stay()?.id===id)draw(host)}
 }
 function draw(host){
  if(!host)return;const s=state(),at=now(),attention=C.attention(s,at),openTasks=[...s.tasks.values()].filter(t=>!C.terminal(t.status));
  const tabs=[['plan','Plan de soins'],['tasks','Tâches horaires'],['transmissions','Transmissions'],['devices','Dispositifs'],['alerts','Alertes · '+attention.length],['vitals','Constantes SSPI / hospitalisation']];
  host.innerHTML=`<div class="nursing-heading"><div><p class="eyebrow">SUIVI INFIRMIER · ${esc(ctx.stay().id)}</p><h3>Dossier infirmier</h3></div><div class="actions"><button type="button" class="primary" id="nursing-write-transmission">Écrire une transmission</button><button class="secondary" id="nursing-clock">Actualiser les échéances</button></div></div><p class="notice">Scénario fictif · les soins planifiés ne remplacent pas une prescription. Les alertes restent visibles dans l’application ; aucune notification externe n’est envoyée.</p>${loadError?`<p class="nursing-error" role="alert">${esc(loadError)} <button id="nursing-retry" class="secondary">Recharger l’équipe</button></p>`:peopleStay!==ctx.stay().id?'<p role="status">Chargement des professionnels habilités pour ce séjour…</p>':''}<div class="nursing-metrics"><div><strong>${[...s.plans.values()].filter(p=>p.status==='Actif').length}</strong><span>plans actifs</span></div><div><strong>${openTasks.length}</strong><span>tâches à suivre</span></div><div><strong>${attention.length}</strong><span>alertes et échéances dépassées</span></div></div><p class="muted">Échéances calculées au ${esc(time(at))}, heure de Paris. Enregistrez vos formulaires puis utilisez Actualiser pour charger les modifications des autres postes.</p><div class="tabs nursing-tabs" aria-label="Rubriques du dossier infirmier">${tabs.map(([key,label])=>`<button data-nursing-pane="${key}" aria-pressed="${pane===key}" class="${pane===key?'active':''}">${label}</button>`).join('')}</div><div id="nursing-panel"></div>`;
  $('#nursing-write-transmission').onclick=()=>{pane='transmissions';draw(host);const note=$('#nursing-transmission textarea[name=observations]');if(note){note.focus();note.scrollIntoView({block:'center',behavior:'smooth'})}};
  $('#nursing-clock').onclick=()=>draw(host);if($('#nursing-retry'))$('#nursing-retry').onclick=()=>loadPeople(ctx.stay().id);
  document.querySelectorAll('[data-nursing-pane]').forEach(b=>b.onclick=()=>{pane=b.dataset.nursingPane;draw(host)});
  ({plan:()=>plans(s),tasks:()=>tasks(s,at),transmissions:()=>transmissions(s),devices:()=>devices(s,at),alerts:()=>alerts(s,attention),vitals:()=>{$('#nursing-panel').innerHTML=ctx.vitals(ctx.stay());ctx.bindVitals(ctx.stay())}})[pane]();
 }
 function plans(s){
  $('#nursing-panel').innerHTML=`<h4>Objectifs et soins planifiés</h4><p>Définissez le soin, l’objectif, le responsable et les horaires retenus par l’équipe. La répétition crée un nombre fini de tâches, sans protocole automatique.</p>${form('nursing-plan',field('title','Intitulé du plan de soins')+text('objective','Objectif et critères de suivi')+text('reference','Prescription / protocole de référence (facultatif)',false)+owner()+field('startAt','Première tâche prévue','datetime-local','')+field('count','Nombre de tâches à créer','number','1','required min="1" max="48" step="1"')+field('interval','Intervalle choisi entre tâches (minutes)','number','','min="1" max="1440" step="1"'),'Créer le plan et ses tâches')}<div class="nursing-list">${[...s.plans.values()].reverse().map(p=>`<article class="nursing-card"><div class="row"><h4>${esc(p.title)}</h4>${badge(p.status)}</div><p class="preserve">${esc(p.objective)}</p>${p.reference?'<p>Référence : '+esc(p.reference)+'</p>':''}${responsible(p)}<p>${[...s.tasks.values()].filter(t=>t.planId===p.id&&C.terminal(t.status)).length} / ${[...s.tasks.values()].filter(t=>t.planId===p.id).length} tâches renseignées</p>${form('nursing-plan-'+p.id,owner(p.ownerId)+select('status','État du plan',[['Actif','Actif'],['Clos','Clos']],p.status)+text('note','Motif / réévaluation'),'Tracer la réévaluation')}${journal(p.id)}</article>`).join('')||'<p class="empty">Aucun plan de soins enregistré.</p>'}</div>`;
  bind('nursing-plan',v=>{
   const count=Number(v.count),interval=Number(v.interval);if(!Number.isInteger(count)||count<1||count>48||count>1&&(!Number.isInteger(interval)||interval<1||interval>1440)||!C.time(v.startAt))return 'Choisissez un début et 1 à 48 tâches ; précisez l’intervalle si elles se répètent.';
   const plan={...base('plan',v),title:v.title.trim(),objective:v.objective.trim(),reference:v.reference.trim()};
   return [plan,...Array.from({length:count},(_,i)=>({...base('task',v),title:plan.title,planId:plan.id,due:C.addMinutes(v.startAt,i*(interval||0))}))];
  });
  for(const p of s.plans.values())bind('nursing-plan-'+p.id,v=>[{...base('plan-update',v),planId:p.id,status:v.status,note:v.note.trim()}]);
 }
 function tasks(s,at){
  const day=taskDay||at.slice(0,10);
  const filtered=[...s.tasks.values()].filter(t=>!taskOwner||t.ownerId===taskOwner).filter(t=>taskScope==='En retard'?!C.terminal(t.status)&&t.due<at:taskScope==='À suivre'?!C.terminal(t.status):true).filter(t=>t.due.slice(0,10)===day||!C.terminal(t.status)&&t.due<day+'T00:00').sort((a,b)=>a.due.localeCompare(b.due));
  $('#nursing-panel').innerHTML=`<h4>Tâches horaires et réalisations</h4><div class="management-toolbar">${field('nursing-day','Journée','date',day)}${select('nursing-scope','Afficher',['Toutes','À suivre','En retard'].map(x=>[x,x]),taskScope)}${select('nursing-owner','Responsable',[['','Tous les responsables'],...people.map(p=>[p.user_id,p.display_name])],taskOwner,false)}</div>${form('nursing-task',field('title','Soin / tâche ponctuelle')+select('planId','Plan de soins (facultatif)',[['','Sans rattachement'],...[...s.plans.values()].filter(p=>p.status==='Actif').map(p=>[p.id,p.title])],'',false)+field('due','Date et heure prévues','datetime-local','')+owner(),'Ajouter la tâche')}<div class="nursing-list">${filtered.map(t=>`<article class="nursing-card ${!C.terminal(t.status)&&t.due<at?'nursing-late':''}"><div class="row"><h4>${esc(time(t.due))} · ${esc(t.title)}</h4>${badge(!C.terminal(t.status)&&t.due<at?'En retard · '+t.status:t.status,!C.terminal(t.status)&&t.due<at)}</div>${responsible(t)}${t.planId?'<p>Plan : '+esc(s.plans.get(t.planId)?.title||t.planId)+'</p>':''}${t.note?'<p class="preserve">'+esc(t.note)+'</p>':''}<p class="muted">Dernière trace : ${esc(t.lastAuthor)} · ${esc(time(t.lastAt))}</p><details><summary>Réaliser, reporter, réattribuer ou rectifier</summary>${form('nursing-task-'+t.id,select('status','État',['À faire','En cours','Réalisée','Non réalisée','Reportée'].map(x=>[x,x]),C.terminal(t.status)?'À faire':'Réalisée')+field('occurredAt','Heure de réalisation / du constat','datetime-local',at)+owner(t.ownerId)+field('rescheduledAt','Nouvelle échéance si report','datetime-local','','')+text('note','Résultat, motif, correction ou non-réalisation',false),'Tracer l’action')}</details>${journal(t.id)}</article>`).join('')||'<p class="empty">Aucune tâche pour ces filtres. Les tâches antérieures non terminées restent affichées.</p>'}</div>`;
  $('input[name="nursing-day"]').onchange=e=>{taskDay=e.target.value;draw($('#nursing-host'))};$('select[name="nursing-scope"]').onchange=e=>{taskScope=e.target.value;draw($('#nursing-host'))};$('select[name="nursing-owner"]').onchange=e=>{taskOwner=e.target.value;draw($('#nursing-host'))};
  bind('nursing-task',v=>[{...base('task',v),title:v.title.trim(),planId:v.planId,due:v.due}]);
  for(const t of filtered)bind('nursing-task-'+t.id,v=>[{...base('task-update',v),taskId:t.id,status:v.status,note:v.note.trim(),rescheduledAt:v.rescheduledAt}]);
 }
 function transmissions(s){
  const entryForm=select('format','Type de transmission',[['Libre','Transmission libre'],['DAR','Transmission ciblée (Données, Actions, Résultats)']],'Libre')+select('context','Contexte',['SSPI','Hospitalisation','Relève','Autre'].map(x=>[x,x]))+field('occurredAt','Date et heure du constat','datetime-local',now())+`<div class="wide" data-transmission-detail hidden>${field('target','Cible / problème suivi','text','','maxlength="250"')}</div>`+text('observations','Transmission / observations')+`<div class="wide" data-transmission-detail hidden>${text('actions','Actions réalisées ou demandées',false)+text('results','Résultats / éléments restant à suivre',false)}</div>`+owner(profile()?.user_id);
  $('#nursing-panel').innerHTML=`<h4>Laisser une transmission</h4><p>Écrivez votre transmission en texte libre ou choisissez le format ciblé. L’auteur est votre compte connecté : <strong>${esc(profile()?.display_name||'Non connecté')}</strong>. La date du constat et l’heure de saisie sont conservées.</p>${form('nursing-transmission',entryForm,'Enregistrer la transmission')}<h4>Transmissions du séjour · ${s.transmissions.length}</h4><div class="nursing-list">${[...s.transmissions].reverse().map(t=>`<article class="nursing-card"><div class="row"><h4>${esc(t.format==='Libre'?'Transmission libre':t.target)} · ${esc(t.context)}</h4><span class="pill">${esc(time(t.occurredAt))}</span></div><p class="preserve">${esc(t.observations)}</p>${t.format!=='Libre'?`<p><strong>Actions :</strong> <span class="preserve">${esc(t.actions||'Non renseignées')}</span></p><p><strong>Résultats :</strong> <span class="preserve">${esc(t.results||'Non renseignés')}</span></p>`:''}${responsible(t)}<p class="muted">Auteur : ${esc(t.authorLabel)} · constat ${esc(time(t.occurredAt))} · saisie ${esc(t.recordedAt)}</p></article>`).join('')||'<p>Aucune transmission enregistrée pour ce séjour.</p>'}</div><details><summary>Transmissions antérieures · ${(ctx.stay().notes||[]).length}</summary>${(ctx.stay().notes||[]).map(n=>`<article class="event"><strong>${esc(n.context)} · ${esc(n.role)}</strong><p>${esc(n.note)}</p><time>${esc(n.at)}</time></article>`).join('')||'<p>Aucune transmission antérieure.</p>'}</details>`;
  const f=$('#nursing-transmission');if(f){const sync=()=>{const targeted=f.elements.namedItem('format').value==='DAR';f.querySelectorAll('[data-transmission-detail]').forEach(el=>el.hidden=!targeted);f.elements.namedItem('target').required=targeted};f.elements.namedItem('format').onchange=sync;sync();}
  bind('nursing-transmission',v=>[{...base('transmission',v),format:v.format,context:v.context,target:v.format==='Libre'?'Transmission libre':v.target.trim(),observations:v.observations.trim(),actions:v.format==='Libre'?'':v.actions.trim(),results:v.format==='Libre'?'':v.results.trim()}]);
 }
 function devices(s,at){
  const deviceTypes=['Voie veineuse périphérique','Cathéter veineux central','Cathéter artériel','Sonde urinaire','Drain','Oxygénothérapie / dispositif respiratoire','Autre dispositif'];
  $('#nursing-panel').innerHTML=`<h4>Surveillance des dispositifs</h4><p>Renseignez les contrôles prévus par l’équipe. Un constat d’anomalie crée une alerte attribuée ; une observation ultérieure ne clôture pas automatiquement cette alerte.</p>${form('nursing-device',select('deviceType','Dispositif',[['','Choisir'],...deviceTypes.map(x=>[x,x])])+field('site','Site / référence du dispositif')+field('placedAt','Date et heure de pose (si connues)','datetime-local','','')+'<label class="check"><input type="checkbox" name="placementUnknown" value="yes"> Date de pose non retrouvée</label>'+field('nextDue','Prochain contrôle prévu','datetime-local','')+text('instructions','Points de surveillance / référence du protocole',false)+owner(),'Enregistrer le dispositif')}<div class="nursing-list">${[...s.devices.values()].reverse().map(d=>`<article class="nursing-card"><div class="row"><h4>${esc(d.deviceType)} · ${esc(d.site)}</h4>${badge(d.status==='Retiré'?'Retiré':d.nextDue<at?'Contrôle échu':'En place',d.status!=='Retiré'&&d.nextDue<at)}</div><p>Pose : ${esc(time(d.placedAt))} · dernier contrôle : ${esc(time(d.lastCheck))}</p>${d.status!=='Retiré'?'<p>Prochain contrôle : '+esc(time(d.nextDue))+'</p>':''}${responsible(d)}<p class="preserve">${esc(d.instructions||'Points de surveillance non renseignés')}</p>${d.findings?'<p><strong>Dernier constat :</strong> '+esc(d.assessment)+' · '+esc(d.findings)+'</p>':''}${d.status!=='Retiré'?`<details><summary>Tracer un contrôle ou le retrait</summary>${form('nursing-device-'+d.id,field('occurredAt','Date et heure du contrôle','datetime-local',at)+select('status','Constat',['Contrôle sans anomalie signalée','Anomalie constatée','Retiré'].map(x=>[x,x]))+text('findings','Observation du site, fixation, fonctionnement et mesures pertinentes')+field('nextDue','Prochain contrôle (sauf retrait)','datetime-local','','')+owner(d.ownerId)+select('level','Priorité si anomalie',['Information','À traiter','Urgente'].map(x=>[x,x]),'À traiter'),'Tracer le contrôle')}</details>`:''}${journal(d.id)}</article>`).join('')||'<p class="empty">Aucun dispositif renseigné.</p>'}</div>`;
  bind('nursing-device',v=>[{...base('device',v),deviceType:v.deviceType,site:v.site.trim(),placedAt:v.placedAt,placementUnknown:v.placementUnknown==='yes',nextDue:v.nextDue,instructions:v.instructions.trim()}]);
  for(const d of s.devices.values())if(d.status!=='Retiré')bind('nursing-device-'+d.id,v=>{const check={...base('device-check',v),deviceId:d.id,status:v.status,findings:v.findings.trim(),nextDue:v.nextDue};return [check,...(v.status==='Anomalie constatée'?[{...base('alert',v),title:'Anomalie · '+d.deviceType+' · '+d.site,note:v.findings.trim(),level:v.level,sourceId:check.id,resolveBy:''}]:[])]});
 }
 function alerts(s,attention){
  $('#nursing-panel').innerHTML=`<h4>Alertes et responsables</h4><p>Les tâches en retard et contrôles échus reprennent leur responsable. Leur signalement disparaît après réalisation, reprogrammation ou retrait tracé. Les alertes déclarées nécessitent une résolution explicite.</p>${form('nursing-alert',field('title','Objet de l’alerte')+select('level','Priorité',['Information','À traiter','Urgente'].map(x=>[x,x]),'À traiter')+text('note','Constat et action attendue')+field('resolveBy','Échéance de traitement (facultative)','datetime-local','','')+owner(),'Créer l’alerte attribuée')}<div class="nursing-list">${attention.map(a=>`<article class="nursing-card ${a.level==='Urgente'?'nursing-urgent':'nursing-late'}"><div class="row"><h4>${esc(a.title)}</h4>${badge(a.level,true)}</div>${responsible(a)}<p>${esc(a.note||a.findings||'Échéance dépassée')}</p>${a.due?'<p>Échéance : '+esc(time(a.due))+'</p>':''}${a.attentionType==='alert'?`<p>État : ${esc(a.status)}</p>${alertAction(a)}${journal(a.id)}`:`<button class="secondary" data-nursing-goto="${a.attentionType==='task'?'tasks':'devices'}">Ouvrir ${a.attentionType==='task'?'les tâches':'les dispositifs'}</button>`}</article>`).join('')||'<p class="empty">Aucune alerte ou échéance dépassée calculée à cette heure. Cela ne constitue pas une évaluation clinique.</p>'}</div><h4>Alertes résolues</h4>${[...s.alerts.values()].filter(a=>a.status==='Résolue').map(a=>`<article class="nursing-card"><h4>${esc(a.title)}</h4>${responsible(a)}<p>${esc(a.note)}</p>${alertAction(a)}${journal(a.id)}</article>`).join('')||'<p>Aucune alerte résolue.</p>'}`;
  bind('nursing-alert',v=>[{...base('alert',v),title:v.title.trim(),level:v.level,note:v.note.trim(),resolveBy:v.resolveBy}]);
  for(const a of s.alerts.values())bind('nursing-alert-'+a.id,v=>[{...base('alert-update',v),alertId:a.id,status:v.status,note:v.note.trim()}]);
  document.querySelectorAll('[data-nursing-goto]').forEach(b=>b.onclick=()=>{pane=b.dataset.nursingGoto;draw($('#nursing-host'))});
 }
 function alertAction(a){return `<details><summary>${a.status==='Résolue'?'Rouvrir l’alerte':'Prendre en charge, réattribuer ou résoudre'}</summary>${form('nursing-alert-'+a.id,select('status','Action',a.status==='Résolue'?[['Ouverte','Réouvrir avec motif']]:[['Prise en charge','Je prends en charge'],['Réattribuée','Réattribuer'],['Résolue','Résoudre']])+owner(a.status==='Résolue'?a.ownerId:profile()?.user_id)+text('note','Action réalisée, réponse ou motif de réattribution'),'Tracer l’action')}</details>`}
 return {render,showPlan:()=>{pane='plan'}};
};
})(typeof window!=='undefined'?window:globalThis);
